    example: { given: "Address 192.0.2.173 with mask 255.255.255.192.", result: "Network address is 192.0.2.128; the mask is /26.", steps: ["173 is 10101101 binary.", "192 in the final mask octet is 11000000.", "AND gives 10000000, which is 128.", "The first three mask octets contribute 24 ones; the last contributes two.", "24 + 2 = 26 prefix bits, leaving six host bits."] },
