    recall: [{ question: "Which IPv6 error reports an oversized forwarded packet?", answer: "ICMPv6 Packet Too Big." }, { question: "What is a PMTU black hole's common symptom?", answer: "Small exchanges work but larger packets repeatedly fail." }],
